      "id": "arxiv:2609.09113v1",
      "title": "SAEScientist-Bench: Can AI Agents Conduct Autonomous SAE Interpretability Research?",
      "url": "https://arxiv.org/abs/2609.09113v1",
      "pdfUrl": "https://arxiv.org/pdf/2609.09113v1",
      "source": "arXiv",
